class Solution:
    def interchangeableRectangles(self, rectangles: List[List[int]]) -> int:
        n = len(rectangles)
        ans = 0
        for i in range(n):
            wi, hi = rectangles[i]
            for j in range(i + 1, n):
                wj, hj = rectangles[j]
                if wi * hj == wj * hi:
                    ans += 1
        return ans

