class Solution {
public:
    long long interchangeableRectangles(vector<vector<int>>& rectangles) {
        int n = rectangles.size();
        long long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if ((long long)rectangles[i][0] * rectangles[j][1] ==
                    (long long)rectangles[j][0] * rectangles[i][1]) ans++;
        return ans;
    }
};

